class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if not needle:
            return 0
        lps = [0] * len(needle)
        k = 0
        for i in range(1, len(needle)):
            while k and needle[i] != needle[k]:
                k = lps[k - 1]
            if needle[i] == needle[k]:
                k += 1
            lps[i] = k
        k = 0
        for i, c in enumerate(haystack):
            while k and c != needle[k]:
                k = lps[k - 1]
            if c == needle[k]:
                k += 1
            if k == len(needle):
                return i - k + 1
        return -1
```

