Study this optimized solution to **Implement Trie (Prefix Tree)**.

```python
class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, word: str) -> None:
        node = self.root
        for c in word:
            node = node.setdefault(c, {})
        node["$"] = True
    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and "$" in node
    def startsWith(self, prefix: str) -> bool:
        return self._walk(prefix) is not None
    def _walk(self, s):
        node = self.root
        for c in s:
            if c not in node:
                return None
            node = node[c]
        return node
```

