class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        target = len(nums) - k
        l, r = 0, len(nums) - 1
        while True:
            pivot, i = nums[r], l
            for j in range(l, r):
                if nums[j] < pivot:
                    nums[i], nums[j] = nums[j], nums[i]
                    i += 1
            nums[i], nums[r] = nums[r], nums[i]
            if i == target:
                return nums[i]
            if i < target:
                l = i + 1
            else:
                r = i - 1
```

