class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        R, C, count = len(grid), len(grid[0]), 0
        for r in range(R):
            for c in range(C):
                if grid[r][c] == "1":
                    count += 1
                    stack = [(r, c)]
                    grid[r][c] = "0"
                    while stack:
                        x, y = stack.pop()
                        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                            if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == "1":
                                grid[nx][ny] = "0"
                                stack.append((nx, ny))
        return count
```

