```python
class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        words = set(wordDict)
        lens = {len(w) for w in words}
        dp = [False] * (len(s) + 1)
        dp[0] = True
        for i in range(1, len(s) + 1):
            for L in lens:
                if L <= i and dp[i - L] and s[i - L:i] in words:
                    dp[i] = True
                    break
        return dp[-1]
```

